# THE RULE:
# 1. Identify rows and cols with >= 2 markers - these are "active"
# 2. Fill any 2-component that touches an active row or active col with 1s.
# 3. Components that don't touch any active row/col remain 2.

def active_lines(markers, H, W):
    """Return list of rows and cols that have >= 2 markers"""
    active_rows = set()
    active_cols = set()
    for r in range(H):
        active_rows.add(r)
    for c in range(W):
        active_cols.add(c)

    # Actually, let me count properly
    rows = {}
    cols = {}
    for r, c in markers:
        rows[r] = rows.get(r, 0) + 1
        cols[c] = cols.get(c, 0) + 1

    return {r for r, c in markers.items() if rows.get(r, 0) >= 2}, {c for c, r in markers.items() if cols.get(c, 0) >= 2}

def component_touches_active_rows_cols(comp, active_rows, active_cols):
    """Check if component touches any active row or col"""
    for r, c in comp:
        if r in active_rows or c in active_cols:
            return True
    return False

